pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 val) internal {
        vm.assume(true);
        uint beforeEther = address(c).balance;
        bool reverted;
        try c.SetMinSum(val) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterMinSum;
        try c.MinSum() returns (uint256 __r) { afterMinSum = __r; } catch { return; }
        uint afterEther = address(c).balance;
        assertTrue(reverted || (afterMinSum == val && afterEther == beforeEther));
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
